        public static string T(string source) {
            if (source == null) return "";
            string[] translations;
            return Entries.TryGetValue(source, out translations) ? translations[Array.IndexOf(Codes, Code)] : source;
        }
        public static void Validate() {
            foreach (var entry in Entries) {
                if (entry.Value.Length != Codes.Length) throw new Exception("Translation count: " + entry.Key);
                foreach (string text in entry.Value) if (string.IsNullOrWhiteSpace(text)) throw new Exception("Empty translation: " + entry.Key);
            }
            string previous = Code;
            foreach (string code in Codes) { Code = code; if (string.IsNullOrEmpty(T("NZB erstellen"))) throw new Exception("Missing primary action"); }
            Code = previous;
        }
    }
